-- Transferir Funciones a través de Relaciones de Oposición: 8 grupos de 3 clases con 3 miembros inventados; opciones = los tres, en audio.
-- Transformación A → B (función contraria) y A → C (misma función, con A no disponible).

begin;

delete from estimulos_rft_base where clase_base_id in (select id from clases_rft_base where programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Transferir Funciones a través de Relaciones de Oposición'));
delete from clases_rft_base where programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Transferir Funciones a través de Relaciones de Oposición');

with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, consignas)
  values ((select id from programas_base where clinica_id is null and nombre = 'Transferir Funciones a través de Relaciones de Oposición'), 'Clase 1', 'Grupo 1', '{"entrenamiento:A→B": "El botón Toba hace lo contrario que el botón Lesu. ¿Qué botón hace lo contrario que el botón Lesu?", "entrenamiento:B→C": "El botón Bori hace lo contrario que el botón Toba. ¿Qué botón hace lo contrario que el botón Toba?", "test_mutuo:B→A": "El botón Toba hace lo contrario que el botón Lesu. ¿Qué botón hace lo contrario que el botón Toba?", "test_mutuo:C→B": "El botón Bori hace lo contrario que el botón Toba. ¿Qué botón hace lo contrario que el botón Bori?", "test_combinatorio:A→C": "El botón Toba hace lo contrario que el botón Lesu. El botón Bori hace lo contrario que el botón Toba. ¿Qué botón hace lo mismo que el botón Lesu?", "test_combinatorio:C→A": "El botón Toba hace lo contrario que el botón Lesu. El botón Bori hace lo contrario que el botón Toba. ¿Qué botón hace lo mismo que el botón Bori?", "transformacion_funciones:A→B": "El botón Lesu enciende la música. El botón Toba hace lo contrario que el botón Lesu. El botón Bori hace lo contrario que el botón Toba. Quiero apagar la música. ¿Qué botón uso?", "transformacion_funciones:A→C": "El botón Lesu enciende la música. El botón Toba hace lo contrario que el botón Lesu. El botón Bori hace lo contrario que el botón Toba. Quiero encender la música, pero el botón Lesu no está. ¿Qué otro botón uso?"}'::jsonb) returning id)
