  values ((select id from programas_base where clinica_id is null and nombre = 'Transferir Funciones a través de Relaciones de Oposición'), 'Clase 24', 'Grupo 8', '{"entrenamiento:A→B": "El mando Nilu hace lo contrario que el mando Mepo. ¿Qué mando hace lo contrario que el mando Nilu?", "entrenamiento:B→C": "El mando Mepo hace lo contrario que el mando Kafi. ¿Qué mando hace lo contrario que el mando Mepo?", "test_mutuo:B→A": "El mando Nilu hace lo contrario que el mando Mepo. ¿Qué mando hace lo contrario que el mando Mepo?", "test_mutuo:C→B": "El mando Mepo hace lo contrario que el mando Kafi. ¿Qué mando hace lo contrario que el mando Kafi?", "test_combinatorio:A→C": "El mando Mepo hace lo contrario que el mando Kafi. El mando Nilu hace lo contrario que el mando Mepo. ¿Qué mando hace lo mismo que el mando Nilu?", "test_combinatorio:C→A": "El mando Mepo hace lo contrario que el mando Kafi. El mando Nilu hace lo contrario que el mando Mepo. ¿Qué mando hace lo mismo que el mando Kafi?", "transformacion_funciones:A→B": "El mando Nilu sube el volumen de la tele. El mando Mepo hace lo contrario que el mando Kafi. El mando Nilu hace lo contrario que el mando Mepo. Quiero bajar el volumen. ¿Qué mando uso?", "transformacion_funciones:A→C": "El mando Nilu sube el volumen de la tele. El mando Mepo hace lo contrario que el mando Kafi. El mando Nilu hace lo contrario que el mando Mepo. Quiero subir el volumen, pero el mando Nilu no está. ¿Qué otro mando uso?"}'::jsonb) returning id)
insert into estimulos_rft_base (clase_base_id, etiqueta, posicion, nombre, concepto_imagen)
select id, x.etiqueta, x.posicion, x.nombre, x.concepto from nueva, (values
  ('A24', 'A', 'El mando Nilu', null),
  ('B24', 'B', 'El mando Mepo', null),
  ('C24', 'C', 'El mando Kafi', null)) x(etiqueta, posicion, nombre, concepto);

update programas_base set
  opciones_clase = true,
  consignas = null,
  secuencia_rft = '[{"fase": "entrenamiento", "origen": "A", "destino": "B"}, {"fase": "entrenamiento", "origen": "B", "destino": "C"}, {"fase": "test_mutuo", "origen": "B", "destino": "A"}, {"fase": "test_mutuo", "origen": "C", "destino": "B"}, {"fase": "test_combinatorio", "origen": "A", "destino": "C"}, {"fase": "test_combinatorio", "origen": "C", "destino": "A"}, {"fase": "transformacion_funciones", "origen": "A", "destino": "B"}, {"fase": "transformacion_funciones", "origen": "A", "destino": "C"}]'::jsonb,
  objetivo = 'El alumno atribuye a un estímulo la función contraria a la del estímulo con el que se relaciona por oposición, y la misma función al contrario del contrario, sin entrenamiento directo de esas funciones ("El botón Mif enciende la música; Tok hace lo contrario que Mif; Dax hace lo contrario que Tok. Quiero apagar la música: ¿qué botón uso?" → Tok).',
  materiales = 'Grupos de 3 (o más) clases con 3 miembros:

A: Estímulo inventado con una función conocida (ej. el botón Mif enciende la música)
B: Estímulo inventado contrario de A
C: Estímulo inventado contrario de B

Los tres miembros de una clase son del mismo tipo (botones, palancas, bebidas, llaves…) y llevan nombres inventados, de forma que solo la red de oposición indica su función. Las funciones de A son de dos polos claros (encender/apagar, abrir/cerrar, caliente/frío, dulce/salado…) y cambian en cada clase. Las opciones son los tres estímulos, dichos uno a uno (en la tableta, tarjetas de audio). Contrapesos: como la oposición es simétrica, en la mitad de las clases la frase dice «Tok hace lo contrario que Mif» y en la otra mitad «Mif hace lo contrario que Tok»; en la mitad de las clases las dos premisas se dicen en orden inverso. Para la prueba de conducta con material, si es posible, un dispositivo real que se encienda y apague.',
  instrucciones_terapeuta = '
Requisito previo: el alumno ha superado "Derivar Relaciones de Oposición en Redes Combinatorias" (dominio 3.2).

Opciones de respuesta: en cada ensayo, diga uno a uno los tres estímulos de la red (ej. «El botón Mif», «El botón Tok», «El botón Dax»); el alumno elige uno. Al estar siempre los tres, el que no corresponde actúa como distractor.

Fase 1 - Entrenamiento (A–B y B–C con la clave "contrario"):

1. Enuncie una sola relación de oposición y pregunte por ella ("El botón Tok hace lo contrario que el botón Mif. ¿Qué botón hace lo contrario que el botón Mif?").
2. No relacione nunca A y C durante el entrenamiento.
3. Refuerce hasta alcanzar el criterio de dominio en ambas relaciones.

Fase 2 - Tests de Vinculación Mutua (B → A, C → B) y Combinatoria (A ↔ C: "¿Qué botón hace lo mismo que el botón Mif?", con las dos premisas en la clave), sin entrenamiento directo. No refuerce diferencialmente durante estos ensayos, pero registre la respuesta.

Fase 3 - Test de Transformación de Funciones, sin entrenamiento directo:

1. Diga la función de A y las dos relaciones de oposición, y plantee un deseo contrario a la función de A: "El botón Mif enciende la música. Tok hace lo contrario que Mif. Dax hace lo contrario que Tok. Quiero apagar la música. ¿Qué botón uso?" (respuesta: Tok, función invertida).
2. Plantee el mismo deseo que la función de A, con A no disponible: "Quiero encender la música, pero el botón Mif no está. ¿Qué otro botón uso?" (respuesta: Dax, función restablecida).
3. No refuerce diferencialmente durante estos ensayos, pero registre la respuesta.
4. Si el alumno responde correctamente, la función de A se ha transformado a través de la red de oposición: invertida en B y restablecida en C. Elegir A en el primer caso indica que no transforma la función; elegir B en el segundo, que no combina las dos oposiciones.
5. Prueba de conducta con material (opcional): con un dispositivo real, "Quiero que se apague la música: pulsa el botón que toca".

Generalización (sondas): redes nuevas con otras funciones (ej. "El agua Kafi está caliente; Somi es lo contrario de Kafi. ¿Cómo está Somi?"), con respuesta oral libre.

Realice el primer bloque de cada test sin ayudas. Si el alumno alcanza el criterio, la relación se considera DERIVADA; si se enseña con ayudas, quedará registrada como DOMINADA (no derivada), aunque el último bloque se realice sin ayudas.

Registro en la app (fase · posición origen → destino; el destino es la respuesta correcta):
- Entrenamiento: A → B ("¿Qué botón hace lo contrario que Mif?") y B → C ("¿Qué botón hace lo contrario que Tok?")
- Test de vínculo mutuo: B → A y C → B
- Test de vínculo combinatorio: A → C ("¿Qué botón hace lo mismo que Mif?") y C → A ("¿Qué botón hace lo mismo que Dax?")
- Transformación de funciones: A → B ("Quiero apagar la música. ¿Qué botón uso?"; función contraria) y A → C ("Quiero encender la música, pero Mif no está. ¿Qué otro botón uso?"; misma función)
Las sondas con los mismos estímulos en otro contexto o con otra persona se registran con las mismas posiciones, eligiendo "Sonda de generalización" como tipo de bloque una vez dominada la combinación.

Grupos de estímulos: los grupos y clases de este programa son un ejemplo. Cree en el PEI del alumno tantos grupos como considere oportuno, incluido un grupo de generalización con estímulos nuevos. En ese grupo, el primer bloque de entrenamiento realizado sin ayudas y sin reforzar diferencialmente funciona como sonda: si el alumno alcanza el criterio a la primera, hay generalización a estímulos nuevos (anótelo en las notas del bloque). Los tests de ese grupo se habilitan cuando su entrenamiento está dominado. Las sondas con los mismos estímulos en otro contexto o con otra persona se registran como "Sonda de generalización" en el grupo ya dominado.'
where clinica_id is null and nombre = 'Transferir Funciones a través de Relaciones de Oposición';

commit;
